SELECT p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate, row_number() OVER(PARTITION BY p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate ORDER BY p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate) AS procedure_rank, COUNT(*) OVER(PARTITION BY p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate) AS procedure_count, SUM(o.amount) OVER(PARTITION BY p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate) AS total_procedure_amount, AVG(i.los) OVER(PARTITION BY p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate) AS avg_los, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) OVER(PARTITION BY p.gender, i.icustay_id, o.order_type, o.order_subtype, o.transaction_type, o.discontinue_of_poe_id, o.statusdescription, o.originalamount, o.originalrate) AS mortality_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN procedureevents o ON i.icustay_id = o.subject_id WHERE p.gender = 'M' AND p.anchor_year BETWEEN 82 AND 92 AND i.first_careunit = 'ICU' AND o.transaction_type = 'Infusion' AND o.order_type = 'Drug' AND o.order_subtype = 'IV' AND o.discontinue_of_poe_id IS NULL AND o.statusdescription IS NOT NULL AND o.originalamount IS NOT NULL AND o.originalrate IS NOT NULL AND procedure_rank <= 24;